/*
 * Configuration. Script Properties (Project Settings -> Script properties)
 * override the defaults:
 *   PROJECT_ID        Firebase project id (default: emailing-portal)
 *   SITE_URL          Firebase Hosting URL (default: https://<PROJECT_ID>.web.app)
 *   FIREBASE_API_KEY  Web API key (default: read from <SITE_URL>/__/firebase/init.json)
 *   APP_SECRET        HMAC secret for tracking links (generated by setup())
 */
var DEFAULT_PROJECT_ID = 'emailing-portal';

var CONFIG = (function () {
  const props = () => PropertiesService.getScriptProperties();
  let settingsCache = null;
  let secretsCache = null;

  function prop(key, fallback) {
    const v = props().getProperty(key);
    return v === null || v === '' ? fallback : v;
  }

  function projectId() {
    return prop('PROJECT_ID', DEFAULT_PROJECT_ID);
  }

  function siteUrl() {
    return String(prop('SITE_URL', settings().site_url || 'https://' + projectId() + '.web.app')).replace(/\/+$/, '');
  }

  function trackingUrl() {
    return settings().tracking_url || ScriptApp.getService().getUrl() || '';
  }

  function apiKey() {
    let key = prop('FIREBASE_API_KEY', '');
    if (!key) {
      const res = UrlFetchApp.fetch(siteUrl() + '/__/firebase/init.json', { muteHttpExceptions: true });
      if (res.getResponseCode() === 200) {
        key = JSON.parse(res.getContentText()).apiKey || '';
        if (key) props().setProperty('FIREBASE_API_KEY', key);
      }
    }
    return key;
  }

  function secret() {
    let s = prop('APP_SECRET', '');
    if (!s) {
      s = Utilities.getUuid() + Utilities.getUuid();
      props().setProperty('APP_SECRET', s);
    }
    return s;
  }

  const DEFAULT_SETTINGS = {
    from_name: 'My Company',
    reply_to: '',
    company_address: '',
    site_url: '',
    tracking_url: '',
    daily_limit: 100,
    per_run_limit: 40,
    dry_run: false,
    crawler_user_agent: 'EmailingLeadFinder/1.0 (Google Apps Script)',
    default_from_email: '',
    default_country_code: '',
    whatsapp_provider: 'chatdaddy',
    chatdaddy_account_id: 'random',
    whatsapp_phone_number_id: '',
    whatsapp_template_language: 'en',
  };

  function settings() {
    if (!settingsCache) settingsCache = Object.assign({}, DEFAULT_SETTINGS, FS.get('settings/app') || {});
    return settingsCache;
  }

  function secrets() {
    if (!secretsCache) secretsCache = FS.get('settings/secrets') || {};
    return secretsCache;
  }

  function senderEmail() {
    return Session.getEffectiveUser().getEmail();
  }

  function reset() {
    settingsCache = null;
    secretsCache = null;
  }

  return { projectId, siteUrl, trackingUrl, apiKey, secret, settings, secrets, senderEmail, reset, DEFAULT_SETTINGS, prop };
})();

// ------------------------------------------------------------------ utilities
function nowIso(date) {
  return (date || new Date()).toISOString();
}

function newToken() {
  return Utilities.getUuid().replace(/-/g, '').slice(0, 24);
}

function hmac(value) {
  const bytes = Utilities.computeHmacSha256Signature(String(value), CONFIG.secret());
  return bytes.map(function (b) { return ('0' + (b & 0xff).toString(16)).slice(-2); }).join('').slice(0, 24);
}

function dayKey(date) {
  return nowIso(date).slice(0, 10);
}

/** Bump the per-day dashboard counters (sent / opens / clicks / replies). */
function bumpDaily(field, n) {
  FS.commit([{ transform: 'stats/daily-' + dayKey(), update: 'stats/daily-' + dayKey(), data: { day: dayKey() }, mustExist: false, increment: { [field]: n || 1 } }]);
}

/** Deadline helper: Apps Script executions are capped at 6 minutes. */
function deadline(ms) {
  const end = Date.now() + ms;
  return function () { return Date.now() < end; };
}
